INSERT INTO `informasi_desa` VALUES (1,'Penyaluran BLT Dana Desa Tahun 2025 Desa Sidomulyo','berita','Pemerintah Desa Sidomulyo Kecamatan Biru-Biru telah secara resmi menyalurkan Bantuan Langsung Tunai (BLT) Dana Desa Tahun 2025 kepada 58 Keluarga Penerima Manfaat (KPM). Penyaluran dilakukan secara transparan di Balai Desa Sidomulyo dipimpin oleh Kepala Desa Satriawan.',NULL,NULL,'2025-03-10','Kaur Umum','publish','2026-07-28 08:47:32','2026-07-28 08:47:32'),(2,'Gotong Royong Kebersihan Lingkungan dan Saluran Air','berita','Masyarakat Desa Sidomulyo bersama Perangkat Desa melaksanakan kegiatan gotong royong kebersihan lingkungan di wilayah Dusun I hingga Dusun VI guna mengantisipasi genangan air pada musim penghujan.',NULL,NULL,'2025-02-15','Kaur Umum','publish','2026-07-28 08:47:32','2026-07-28 08:47:32'),(3,'Pengumuman Pelayanan Administrasi Surat Keterangan Online','pengumuman','Diberitahukan kepada seluruh warga Desa Sidomulyo bahwa pengurusan Surat Keterangan (Domisili, SKTM, Usaha, Akte Nikah, Belum Menikah, Belum Punya Rumah, Kematian, dan Mandah) kini dapat diajukan secara online melalui Sistem Informasi Desa Sidomulyo.',NULL,NULL,'2025-03-01','Kaur Umum','publish','2026-07-28 08:47:32','2026-07-28 08:47:32'),(4,'Musyawarah Perencanaan Pembangunan Desa (Musrenbangdes) 2025','agenda','Agenda kegiatan Musrenbangdes Sidomulyo dalam rangka penyusunan rencana kerja pembangunan desa dan penetapan prioritas anggaran tahun mendatang.','2025-04-05 09:00:00',NULL,'2025-03-20','Kaur Umum','publish','2026-07-28 08:47:32','2026-07-28 08:47:32'),(5,'Dokumentasi Kantor dan Pelayanan Desa Sidomulyo','galeri','Dokumentasi suasana kantor dan kegiatan pelayanan administrasi di Kantor Kepala Desa Sidomulyo Kecamatan Biru-Biru.',NULL,'profil/kantor-desa.jpeg','2025-01-01','Kaur Umum','publish','2026-07-28 08:47:32','2026-07-28 08:47:32');
/*!40000 ALTER TABLE `informasi_desa` ENABLE KEYS */;
