DROP TABLE IF EXISTS `penerima_bantuan`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `penerima_bantuan` (
  `id_penerima` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `id_penduduk` bigint(20) unsigned NOT NULL,
  `program_bantuan` varchar(100) NOT NULL,
  `keterangan` varchar(150) DEFAULT NULL,
  `tanggal_terima` date NOT NULL,
  `status` enum('diterima','dialihkan') NOT NULL DEFAULT 'diterima',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id_penerima`),
  KEY `penerima_bantuan_id_penduduk_foreign` (`id_penduduk`),
  CONSTRAINT `penerima_bantuan_id_penduduk_foreign` FOREIGN KEY (`id_penduduk`) REFERENCES `penduduk` (`id_penduduk`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=59 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
